<script setup>
import { computed, ref, watch, nextTick } from 'vue';
import VisualRegionPicker from './VisualRegionPicker.vue';
import { clone, uniqueId, excludeGraphItem, deleteGraphItem, resizeTable, splitCell, mergeCells, draftProblems } from '../visualEditing.js';
import { reviewProblems } from '../visualReviewForm.js';
const props = defineProps({ asset: Object, busy: Boolean, issues: {type:Array,default:()=>[]} });
const emit = defineEmits(['save', 'cancel']);
const draft = ref(null), reason = ref(''), confirmed = ref(false), resolutions=ref([]), selected=ref(''), form=ref(null), merge=ref({row:1,column:1,rows:1,columns:2}), localError=ref(''), regionHost=ref(null);
watch(() => props.asset.id, () => { draft.value=clone(props.asset.extraction); draft.value.tables ||= []; draft.value.graphs ||= []; draft.value.uncertainties ||= []; reason.value=''; confirmed.value=false; selected.value=''; resolutions.value=props.issues.filter(i=>i.severity!=='info').map(i=>({...i,disposition:'',reason:'',targets:[]})); }, {immediate:true});
const targets=computed(()=>draft.value.graphs.flatMap((graph,gi)=>['groups','nodes','edges'].flatMap(kind=>graph[kind].map((item,index)=>({path:`graphs/${gi}/${kind}/${index}`,item,graph,kind,index,label:`图 ${gi+1} · ${kind==='groups'?'分组':kind==='nodes'?'节点':'连线'} ${item.label || (kind==='edges'?`${label(graph,item.source)} → ${label(graph,item.target)}`:'无可见标题')}（${index+1}）`})))));
const issueTargets=computed(()=>[...targets.value,...Object.entries({kind:'图片类型',title:'可见标题',description:'内容说明',body_text:'正文图注',transcription:'提取文字',graphs:'关系图整体结构（含增删）',tables:'表格整体结构（含增删）'}).filter(([path])=>path!=='transcription' || (!draft.value.graphs.length && !draft.value.tables.length)).map(([path,label])=>({path,label})),...draft.value.graphs.map((graph,gi)=>({path:`graphs/${gi}`,label:`图 ${gi+1} 整体结构`})),...draft.value.tables.flatMap((table,ti)=>[{path:`tables/${ti}`,label:`表 ${ti+1} 完整结构与内容`},...['title','notes','header_rows'].map(key=>({path:`tables/${ti}/${key}`,label:`表 ${ti+1} ${key==='notes'?'条件与注释':key==='title'?'标题':'表头范围'}`})),...table.cells.map((cell,ci)=>({path:`tables/${ti}/cells/${ci}`,label:`表 ${ti+1} · 第 ${cell.row+1} 行第 ${cell.column+1} 列：${cell.text}`,item:cell}))])]);
const identities=new WeakMap();let nextIdentity=0;
function identity(object) { if(!identities.has(object)) identities.set(object,++nextIdentity);return identities.get(object); }
watch(()=>[...draft.value.graphs.flatMap(g=>[identity(g),...g.groups.map(identity),...g.nodes.map(identity),...g.edges.map(identity)]),...draft.value.tables.flatMap(t=>[identity(t),...t.cells.map(identity)])].join(','),(after,before)=>{if(before!==undefined && after!==before) {resolutions.value.forEach(r=>r.targets=[]);selected.value='';localError.value='结构数量或顺序已变化，请重新关联各问题的对象，避免核对位置错配。';}});
watch(selected,async()=>{await nextTick();regionHost.value?.scrollIntoView?.({block:'start',behavior:'smooth'});});
function returnToTarget() { form.value?.querySelector(`[data-target="${selected.value}"]`)?.scrollIntoView?.({block:'center',behavior:'smooth'}); }
const selectedTarget=computed(()=>targets.value.find(t=>t.path===selected.value));
const structureProblems = computed(() => draftProblems(draft.value));
const issueStates = computed(() => resolutions.value.map(item => {
  const problems = reviewProblems(item, props.asset.extraction, draft.value);
  return { problems, tone: problems.some(p => p.invalid) ? 'invalid' : problems.length ? 'pending' : 'resolved' };
}));
const completedCount = computed(() => issueStates.value.filter(s => s.tone === 'resolved').length);
const statusText = { pending: '待处理', invalid: '需要修改', resolved: '已完成' };
const blockers = computed(() => [
  ...structureProblems.value,
  ...issueStates.value.flatMap((state, index) => state.problems.map(problem => ({ ...problem, issueId: resolutions.value[index].id, message: `问题 ${index + 1}：${problem.message}` }))),
  ...(!reason.value.trim() ? [{ target: 'review-reason', message: '请填写本次修订说明。' }] : []),
  ...(!confirmed.value ? [{ target: 'review-confirmation', message: '请对照原图检查后，勾选确认保留内容。' }] : []),
  ...(!changed.value ? [{ target: 'description', message: '尚未修改识别内容或记录问题核对结果。' }] : []),
]);
function issueFieldError(index, field) { return issueStates.value[index].problems.find(p => p.field === field); }
function setDisposition(item) { item.targets = []; }
function fieldTone(path) {
  if (structureProblems.value.some(p => p.target === path || p.target.startsWith(path + '/'))) return 'review-field-invalid';
  const related = resolutions.value.map((item, i) => ({ item, state: issueStates.value[i] })).filter(({item}) =>
    [...item.targets, item.scope].filter(Boolean).some(target => target === path || target.startsWith(path + '/') || path.startsWith(target + '/')));
  if (related.some(({state}) => state.tone === 'invalid')) return 'review-field-invalid';
  if (related.some(({state}) => state.tone === 'pending')) return 'review-field-pending';
  if (related.length) return 'review-field-resolved';
  return '';
}
async function focusProblem(problem) {
  await nextTick();
  const host = problem.issueId ? form.value?.querySelector(`[data-issue="${problem.issueId}"]`) : form.value;
  if (problem.issueId && host) host.open = true;
  const aggregate = ['graphs', 'tables'].includes(problem.target) ? host?.querySelector(`[data-target="${problem.target}/0"]`) : null;
  const target = problem.issueId ? host?.querySelector(`[data-review-field="${problem.field}"]`) : aggregate || host?.querySelector(`[data-target="${problem.target}"]`);
  const field = target?.matches('input,textarea,select,button') ? target : target?.querySelector('input,textarea,select') || target?.querySelector('button');
  target?.scrollIntoView?.({ block: 'center', behavior: 'smooth' });
  field?.focus({ preventScroll: true });
}
function excerpts(item) {
  const values = [...item.message.matchAll(/[“「『"']([^”」』"'\n]{2,160})[”」』"']/g)].map(match => match[1]);
  return [...new Set(values)].flatMap(text => ['transcription', 'body_text', 'description', 'title'].filter(path => path !== 'transcription' || (!draft.value.graphs.length && !draft.value.tables.length)).flatMap(path => {
    const value = draft.value[path] || '', start = value.indexOf(text);
    return start < 0 ? [] : [{ path, start, text }];
  })).slice(0, 4);
}
async function focusExcerpt(excerpt) {
  await focusProblem({ target: excerpt.path });
  const field = form.value?.querySelector(`[data-target="${excerpt.path}"] textarea, [data-target="${excerpt.path}"] input`);
  field?.setSelectionRange(excerpt.start, excerpt.start + excerpt.text.length);
}
const applicableTargets = item => item.disposition === 'excluded' ? targets.value : issueTargets.value;
const changed=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(props.asset.extraction) || resolutions.value.length>0);
const sortedCells=table=>[...table.cells].sort((a,b)=>a.row-b.row||a.column-b.column);
function label(graph,id) { const x=[...graph.nodes,...graph.groups].find(x=>x.id===id); return x?.label || `无标题对象 ${id}`; }
function addGraph() { draft.value.kind=draft.value.tables.length?'mixed':'diagram'; draft.value.graphs.push({direction:'LR',groups:[],nodes:[{id:'n1',label:'',group:null,shape:'rectangle',review_status:'confirmed',bbox:null,bbox_basis:'unverified'}],edges:[],uncertainties:[]}); }
function addItem(graph,kind) { if(kind==='edges') { const id=graph.nodes[0]?.id || graph.groups[0]?.id; if(!id) return; graph.edges.push({source:id,target:id,label:'',direction:'forward',style:'solid',condition:'',review_status:'confirmed',bbox:null,bbox_basis:'unverified'}); } else { const base={id:uniqueId(graph,kind==='groups'?'g':'n'),label:'',bbox:null,bbox_basis:'unverified',review_status:'confirmed'}; graph[kind].push(kind==='groups'?{...base,parent:null,direction:'LR'}:{...base,group:null,shape:'rectangle'}); } }
function addTable() { draft.value.kind=draft.value.graphs.length?'mixed':'table'; draft.value.tables.push({title:'',rows:2,columns:2,header_rows:1,notes:[],cells:[0,1,2,3].map(i=>({row:Math.floor(i/2),column:i%2,rowspan:1,colspan:1,text:''}))}); }
function region(bbox) { if(selectedTarget.value) { selectedTarget.value.item.bbox=bbox; selectedTarget.value.item.bbox_basis=bbox?'human':'unverified'; } }
function excludeTarget(path) { const t=targets.value.find(x=>x.path===path); if(t) excludeGraphItem(t.graph,t.kind,t.index); }
function doMerge(table) { localError.value=mergeCells(table,Number(merge.value.row)-1,Number(merge.value.column)-1,Number(merge.value.rows),Number(merge.value.columns))?'':'合并范围越界或切开了已有合并单元格，请先拆分该单元格。'; }
async function focusIssue(id) { await nextTick(); const field=form.value?.querySelector(`[data-issue="${id}"]`); if(field) field.open=true; field?.scrollIntoView?.({block:'center',behavior:'smooth'}); field?.querySelector('select')?.focus(); }
function save() { if(props.busy || blockers.value.length) return; const extraction=clone(draft.value); extraction.uncertainties=[]; extraction.graphs.forEach(g=>g.uncertainties=[]); emit('save',{extraction,reason:reason.value.trim(),resolutions:resolutions.value.map(r=>({issue_id:r.id,disposition:r.disposition,reason:r.reason.trim(),targets:r.targets}))}); }
defineExpose({focusIssue});
</script>
<template><form ref="form" class="visual-editor" novalidate tabindex="-1" @submit.prevent="save"><div class="section-toolbar"><div><h3>对照原图修订</h3><p class="small muted">提交本图复核后生成新版本；其余图片沿用原结果和状态，不会重新识别。复核发布后生效。</p></div><button type="button" class="btn" @click="emit('cancel')">取消修订</button></div>
<template v-if="draft">
<div class="review-overview"><div><strong>复核进度 · {{ completedCount }} / {{ resolutions.length }} 项已完成</strong><p>只需处理识别疑点；原识别正确时选择“已核对”，不必修改内容。</p></div><div class="review-legend"><span class="review-badge pending">! 待处理</span><span class="review-badge invalid">× 需要修改</span><span class="review-badge resolved">✓ 已完成</span></div></div>
<div v-if="structureProblems.length" class="review-structure-errors" role="status"><strong>图片内容结构需要调整</strong><button v-for="problem in structureProblems" :key="problem.target + problem.message" type="button" class="review-jump" @click="focusProblem(problem)">{{ problem.message }} <span>定位修改 →</span></button></div>
<div class="editor-grid"><label class="field-label" data-target="kind" :class="fieldTone('kind')">图片类型<select v-model="draft.kind" :aria-invalid="structureProblems.some(p=>p.target==='kind')" :aria-describedby="structureProblems.some(p=>p.target==='kind') ? `kind-error-${asset.id}` : undefined"><option value="diagram">关系图 / 流程图</option><option value="table">表格</option><option value="mixed">混合内容</option><option value="photo">照片</option><option value="chart">统计图</option><option value="text">文字图片</option><option value="unknown">类型待确认</option></select><span v-if="structureProblems.some(p=>p.target==='kind')" :id="`kind-error-${asset.id}`" class="review-field-message">{{ structureProblems.find(p=>p.target==='kind').message }}</span></label><label class="field-label" data-target="title" :class="fieldTone('title')">可见标题<input v-model="draft.title" placeholder="原图没有标题可留空"/></label></div>
<label class="field-label" data-target="description" :class="fieldTone('description')">可见内容说明<textarea v-model="draft.description" rows="3"/></label>
<section v-if="resolutions.length" class="review-issues">
  <h4>逐项处理识别问题</h4><p class="small muted">选择“已经修正”时需关联确实修改过的内容；看不清的关系对象可以明确排除。</p>
  <p class="review-progress" role="status">{{ resolutions.length }} 项需要处理 · {{ completedCount }} 项已完成 · {{ resolutions.length - completedCount }} 项未完成</p>
  <details v-for="(item,ri) in resolutions" :key="item.id" :data-issue="item.id" :class="['review-issue', `review-issue-${issueStates[ri].tone}`]" :open="ri===0">
    <summary><span class="review-badge" :class="issueStates[ri].tone">{{ issueStates[ri].tone==='resolved'?'✓':issueStates[ri].tone==='invalid'?'×':'!' }} {{ statusText[issueStates[ri].tone] }}</span><span>问题 {{ ri+1 }}：{{ item.message.slice(0,90) }}{{ item.message.length>90?'…':'' }}</span></summary>
    <p class="review-problem-text">{{ item.message }}</p>
    <div v-if="excerpts(item).length" class="review-evidence"><span>识别文字中的对应片段，点击后选中文字；请对照原图核对。</span><button v-for="excerpt in excerpts(item)" :key="excerpt.path+excerpt.start" type="button" @click="focusExcerpt(excerpt)"><mark>{{ excerpt.text }}</mark><span>定位文字 →</span></button></div>
    <label class="field-label" :class="{'review-field-pending':!item.disposition}">处理结果 <span class="review-required">必填</span><select v-model="item.disposition" data-review-field="disposition" :aria-label="`问题 ${ri+1} 处理结果`" @change="setDisposition(item)"><option value="">请选择</option><option value="corrected">识别有误，已经修正</option><option value="confirmed">已核对，原识别正确</option><option value="excluded">无法确认，排除相关对象</option></select></label>
    <p v-if="item.disposition==='confirmed'" class="review-confirmed-note">无需修改识别文字，也无需关联修正字段；填写下方核对依据即可。</p>
    <template v-if="['corrected','excluded'].includes(item.disposition)">
      <label class="field-label" :class="issueFieldError(ri,'targets') ? `review-field-${issueFieldError(ri,'targets').invalid?'invalid':'pending'}` : ''">关联修正字段 / 对象（可多选） <span class="review-required">必填</span><select v-model="item.targets" data-review-field="targets" multiple :aria-label="`问题 ${ri+1} 关联对象`" :aria-invalid="!!issueFieldError(ri,'targets')?.invalid" :aria-describedby="`target-error-${asset.id}-${ri}`"><option v-for="target in applicableTargets(item)" :key="target.path" :value="target.path">{{ target.label }}</option></select><span class="small muted">可按住 Ctrl / Command 选择多个；下方按钮可跳到所选字段。</span><span :id="`target-error-${asset.id}-${ri}`" class="review-field-message">{{ issueFieldError(ri,'targets')?.message }}</span></label>
      <div class="review-target-links"><button v-for="path in item.targets" :key="path" type="button" class="review-jump" @click="focusProblem({target:path})">修改：{{ issueTargets.find(t=>t.path===path)?.label }} →</button></div>
      <button v-if="item.disposition==='excluded'" type="button" class="btn" :disabled="!item.targets.length" @click="item.targets.forEach(excludeTarget)">排除选中对象及关联连线</button>
    </template>
    <label class="field-label" :class="issueFieldError(ri,'reason') ? `review-field-${issueFieldError(ri,'reason').invalid?'invalid':'pending'}` : ''">核对依据 / 修正说明 <span class="review-required">必填 · 至少 2 个字符</span><textarea v-model="item.reason" data-review-field="reason" rows="2" minlength="2" maxlength="2000" :aria-label="`问题 ${ri+1} 核对说明`" :aria-invalid="!!issueFieldError(ri,'reason')?.invalid" :aria-describedby="`reason-error-${asset.id}-${ri}`" placeholder="例如：已对照原图第 3 行，识别文字与原图一致。"/><span :id="`reason-error-${asset.id}-${ri}`" class="review-field-message">{{ issueFieldError(ri,'reason')?.message || '✓ 核对说明已填写' }}</span></label>
  </details>
</section>
<div class="visual-actions"><button type="button" class="btn" data-target="graphs" @click="addGraph">添加关系图</button><button type="button" class="btn" data-target="tables" @click="addTable">添加表格</button></div>
<section v-for="(graph,gi) in draft.graphs" :key="gi" :data-target="`graphs/${gi}`" :class="['editor-graph',fieldTone(`graphs/${gi}`)]"><div class="section-toolbar"><h4>关系图 {{ gi+1 }}</h4><button type="button" class="btn" @click="draft.graphs.splice(gi,1)">删除误识别的整张关系图</button></div><p class="small muted">删除用于原图不存在的误识别；看不清的真实对象请使用“排除”，其连接与条件仍会保留在审核记录中。</p><label class="field-label">展示方向<select v-model="graph.direction"><option value="LR">从左到右</option><option value="TB">从上到下</option><option value="RL">从右到左</option><option value="BT">从下到上</option></select></label>
<div class="visual-actions"><button type="button" class="btn" @click="addItem(graph,'groups')">添加分组</button><button type="button" class="btn" @click="addItem(graph,'nodes')">添加节点</button><button type="button" class="btn" @click="addItem(graph,'edges')">添加连线</button></div>
<fieldset v-for="(group,index) in graph.groups" :key="group.id" :data-target="`graphs/${gi}/groups/${index}`" :class="['graph-item',fieldTone(`graphs/${gi}/groups/${index}`)]"><legend>分组 {{ index+1 }}</legend><div class="editor-grid"><label>可见名称<input v-model="group.label" :aria-label="`图 ${gi+1} 分组 ${group.id}`"/></label><label>上级分组<select v-model="group.parent"><option :value="null">最外层</option><option v-for="g in graph.groups.filter(g=>g.id!==group.id)" :key="g.id" :value="g.id">{{ g.label || `无标题分组 ${g.id}` }}</option></select></label><label>内部方向<select v-model="group.direction"><option v-for="d in ['LR','TB','RL','BT']" :key="d">{{ d }}</option></select></label></div><div class="visual-actions"><button type="button" class="btn small-button" @click="selected=`graphs/${gi}/groups/${index}`">标记原图位置</button><button type="button" class="btn small-button" @click="excludeGraphItem(graph,'groups',index)">{{ group.review_status==='excluded'?'已排除分组及内部关系':'排除分组及内部关系' }}</button><button v-if="['excluded','pending'].includes(group.review_status)" type="button" class="btn small-button" @click="group.review_status='confirmed'">重新确认此分组</button><button type="button" class="btn small-button" @click="deleteGraphItem(graph,'groups',index)">删除误识别分组</button></div></fieldset>
<fieldset v-for="(node,index) in graph.nodes" :key="node.id" :data-target="`graphs/${gi}/nodes/${index}`" :class="['graph-item',fieldTone(`graphs/${gi}/nodes/${index}`)]"><legend>节点 {{ index+1 }}</legend><div class="editor-grid"><label>可见名称<input v-model="node.label" :aria-label="`图 ${gi+1} 节点 ${node.id}`"/></label><label>所属分组<select v-model="node.group"><option :value="null">最外层</option><option v-for="g in graph.groups" :key="g.id" :value="g.id">{{ g.label || `无标题分组 ${g.id}` }}</option></select></label><label>形状<select v-model="node.shape"><option value="rectangle">矩形</option><option value="rounded">圆角</option><option value="diamond">判断菱形</option><option value="database">数据库</option><option value="circle">圆形</option></select></label></div><div class="visual-actions"><button type="button" class="btn small-button" @click="selected=`graphs/${gi}/nodes/${index}`">标记原图位置</button><button type="button" class="btn small-button" @click="excludeGraphItem(graph,'nodes',index)">{{ node.review_status==='excluded'?'已排除此节点及连线':'排除此节点及连线' }}</button><button v-if="['excluded','pending'].includes(node.review_status)" type="button" class="btn small-button" @click="node.review_status='confirmed'">重新确认此节点</button><button type="button" class="btn small-button" @click="deleteGraphItem(graph,'nodes',index)">删除误识别节点</button></div></fieldset>
<fieldset v-for="(edge,ei) in graph.edges" :key="ei" :data-target="`graphs/${gi}/edges/${ei}`" :class="['graph-item',fieldTone(`graphs/${gi}/edges/${ei}`)]"><legend>连线 {{ ei+1 }}{{ edge.review_status==='excluded'?' · 已排除':'' }}</legend><div class="editor-grid"><label>起点<select v-model="edge.source"><option v-for="n in [...graph.nodes,...graph.groups]" :key="n.id" :value="n.id">{{ label(graph,n.id) }}（{{ n.id }}）</option></select></label><label>终点<select v-model="edge.target"><option v-for="n in [...graph.nodes,...graph.groups]" :key="n.id" :value="n.id">{{ label(graph,n.id) }}（{{ n.id }}）</option></select></label><label>方向<select v-model="edge.direction"><option value="forward">起点 → 终点</option><option value="both">双向 ↔</option><option value="none">无箭头 —</option></select></label><label>线型<select v-model="edge.style"><option value="solid">实线</option><option value="dashed">虚线</option></select></label><label>连线文字<input v-model="edge.label"/></label><label>可见前提 / 分支条件<input v-model="edge.condition" placeholder="例如：检测失败；仅填写原图明确给出的条件"/></label></div><div class="visual-actions"><button type="button" class="btn small-button" @click="selected=`graphs/${gi}/edges/${ei}`">标记原图位置</button><button type="button" class="btn small-button" @click="edge.review_status=edge.review_status==='excluded'?'confirmed':'excluded'">{{ edge.review_status==='excluded'?'重新确认此连线':'排除此连线' }}</button><button type="button" class="btn small-button" @click="deleteGraphItem(graph,'edges',ei)">删除误识别连线</button><button v-if="edge.review_status==='pending'" type="button" class="btn small-button" @click="edge.review_status='confirmed'">确认保留此连线</button></div></fieldset></section>
<section v-if="targets.length" ref="regionHost" class="region-editor"><label class="field-label">原图定位对象<select v-model="selected"><option value="">选择对象</option><option v-for="target in targets" :key="target.path" :value="target.path">{{ target.label }}</option></select></label><VisualRegionPicker :asset="asset" :target="selectedTarget?.item" @select="region"/><button v-if="selectedTarget" type="button" class="btn" @click="returnToTarget">返回此对象的结构字段</button></section>
<section v-for="(table,ti) in draft.tables" :key="ti" :data-target="`tables/${ti}`" :class="['editor-table',fieldTone(`tables/${ti}`)]"><div class="section-toolbar"><h4>表格 {{ ti+1 }} · {{ table.rows }} 行 × {{ table.columns }} 列</h4><button type="button" class="btn" @click="draft.tables.splice(ti,1)">删除误识别表格</button></div><div class="editor-grid"><label :data-target="`tables/${ti}/title`" :class="fieldTone(`tables/${ti}/title`)">可见标题<input v-model="table.title"/></label><label :data-target="`tables/${ti}/header_rows`" :class="fieldTone(`tables/${ti}/header_rows`)">表头行数<input v-model.number="table.header_rows" type="number" min="0" :max="table.rows"/></label></div><div class="visual-actions"><button type="button" class="btn" @click="resizeTable(table,'row',table.rows)">末尾添加行</button><button type="button" class="btn" @click="resizeTable(table,'column',table.columns)">末尾添加列</button></div><div class="visual-table"><table><thead><tr><th>位置</th><th>修订内容</th><th>结构</th></tr></thead><tbody><tr v-for="cell in sortedCells(table)" :key="`${cell.row}-${cell.column}`" :data-target="`tables/${ti}/cells/${table.cells.indexOf(cell)}`" :class="fieldTone(`tables/${ti}/cells/${table.cells.indexOf(cell)}`)"><td>{{ cell.row+1 }} 行 / {{ cell.column+1 }} 列<br/>跨 {{ cell.rowspan }} 行 × {{ cell.colspan }} 列</td><td><textarea v-model="cell.text" rows="2" :aria-label="`表格 ${ti+1} 第 ${cell.row+1} 行第 ${cell.column+1} 列`"/></td><td><div class="cell-actions"><button type="button" class="btn small-button" @click="resizeTable(table,'row',cell.row)">上方插行</button><button type="button" class="btn small-button" @click="resizeTable(table,'column',cell.column)">左侧插列</button><button type="button" class="btn small-button" :disabled="table.rows===1" @click="resizeTable(table,'row',cell.row,true)">删此行</button><button type="button" class="btn small-button" :disabled="table.columns===1" @click="resizeTable(table,'column',cell.column,true)">删此列</button><button v-if="cell.rowspan>1 || cell.colspan>1" type="button" class="btn small-button" @click="splitCell(table,cell)">拆分单元格</button></div></td></tr></tbody></table></div><div class="editor-grid"><label>合并起始行<input v-model.number="merge.row" type="number" min="1" :max="table.rows"/></label><label>合并起始列<input v-model.number="merge.column" type="number" min="1" :max="table.columns"/></label><label>合并行数<input v-model.number="merge.rows" type="number" min="1" :max="table.rows"/></label><label>合并列数<input v-model.number="merge.columns" type="number" min="1" :max="table.columns"/></label></div><button type="button" class="btn" @click="doMerge(table)">合并范围（保留已有文字）</button><label v-for="(_,ni) in table.notes" :key="ni" :data-target="ni===0?`tables/${ti}/notes`:undefined" :class="['field-label',fieldTone(`tables/${ti}/notes`)]">单位 / 条件 / 注释 {{ ni+1 }}<textarea v-model="table.notes[ni]"/><button type="button" class="btn small-button" @click="table.notes.splice(ni,1)">删除误识别注释</button></label><button type="button" :data-target="!table.notes.length?`tables/${ti}/notes`:undefined" class="btn" @click="table.notes.push('')">添加原图注释</button></section>
<p v-if="draft.tables.length || draft.graphs.length" class="small muted">结构变化会同步重建提取文字，旧自动说明会被清除。排除关系后仅使用保留的明确事实，自动移除自由说明、正文图注和旧转写，避免它们重新带入已排除关系；保留内容不会作为完整流程。</p><label v-if="!draft.tables.length && !draft.graphs.length" class="field-label" data-target="transcription" :class="fieldTone('transcription')">提取文字<textarea v-model="draft.transcription" rows="5"/></label><label class="field-label" data-target="body_text" :class="fieldTone('body_text')">正文 / 图注<textarea v-model="draft.body_text" rows="3"/></label><label class="field-label" data-target="review-reason" :class="{'review-field-pending':!reason.trim()}">本次修订说明<textarea v-model="reason" rows="2" required maxlength="2000" placeholder="记录本次整体修订范围和核对依据。"/></label><label class="check-row" data-target="review-confirmation" :class="{'review-field-pending':!confirmed}"><input v-model="confirmed" type="checkbox"/>我已对照原图确认保留内容及其位置、连接、数字和条件；无法确认的内容已明确排除。</label><p v-if="localError" class="notice warning">{{ localError }}</p>
<div class="review-submit-panel" :class="{ready:!blockers.length}">
  <details v-if="blockers.length" open class="review-blockers" :id="`review-errors-${asset.id}`"><summary>还不能提交：{{ blockers.length }} 项未完成 <span>点击具体提示可定位</span></summary><ul><li v-for="(problem,index) in blockers" :key="index"><button type="button" class="review-jump" :class="{invalid:problem.invalid}" @click="focusProblem(problem)">{{ problem.message }} <span>去处理 →</span></button></li></ul></details>
  <p v-else class="review-ready" role="status">✓ 所有必填项及内容结构检查已完成，可以提交。</p>
  <div class="review-submit-actions"><span>{{ completedCount }} / {{ resolutions.length }} 项问题已完成</span><button v-if="blockers.length" type="button" class="btn" @click="focusProblem(blockers[0])">定位第一项未完成</button><button class="btn primary" :disabled="busy || blockers.length>0" :aria-describedby="blockers.length ? `review-errors-${asset.id}` : undefined">{{ busy?'正在提交…':'确认修订并生成新版本' }}</button></div>
</div></template></form>
</template>
